private void UpdateDisplay(int casinoCash)
{
    int wonBalance = casinoCash * CoinManager.WonPerPoint;
    casinoCashText.text = $"도박 앱 잔액  {wonBalance:N0}원";
    if (home_cashText != null)
        home_cashText.text = $"보유 금액  {wonBalance:N0}원";

    foreach (TMP_Text text in GetComponentsInChildren<TMP_Text>(true))
    {
        if (text == null || ReferenceEquals(text, casinoCashText) || ReferenceEquals(text, home_cashText))
            continue;

        string current = text.text ?? string.Empty;
        if (current.Contains("Cash:") || current.Contains('$') ||
            current.Contains("사이트 포인트") || current.Contains("보유 포인트"))
        {
            text.text = $"도박 앱 잔액  {wonBalance:N0}원";
        }
    }
}

private void OnCashButtonClicked(int won)
{
    if (CoinManager.Instance == null)
    {
        ShowPopup("출금 실패", "은행 정보를 불러올 수 없습니다.");
        return;
    }

    if (CoinManager.Instance.TryChargeToCasino(won, out ChargeToCasinoFailureReason failureReason))
    {
        ShowRechargeStatus($"{won:N0}원 충전 완료", false);
        return;
    }

    if (failureReason == ChargeToCasinoFailureReason.InsufficientBankCash)
    {
        ShowRechargeStatus("통장 잔액이 부족합니다.", true);
        return;
    }

    ShowRechargeStatus("선택할 수 없는 충전 금액입니다.", true);
}

private void EvaluateResult(SlotSymbol[] results)
{
    bool allSame = IsAllSame(results);
    int payout = 0;
    stakeCommitted = false;

    if (allSame)
    {
        float multiplier = Mathf.Max(2f, results[0].payoutMultiplier);
        payout = CalculatePayout(betAmount, multiplier);
        int profit = payout - betAmount;
        int payoutWon = payout * CoinManager.WonPerPoint;
        int profitWon = profit * CoinManager.WonPerPoint;
        resultText.text = $"{multiplier:0.#}배 당첨! {payoutWon:N0}원 지급 (순이익 +{profitWon:N0}원)";
        resultText.color = new Color(1f, 0.78f, 0.12f);
        CoinManager.Instance.AddCasinoCredit(payout);
        StartCoroutine(ShowWinCelebration(payout, multiplier, profit));
    }
    else
    {
        resultText.text = "꽝";
        resultText.color = Color.black;
    }

    spinButton.interactable = true;
    UpdateUI(CoinManager.Instance.CasinoCash);
    SpinResolved?.Invoke(allSame, payout);
}

private void UpdateUI(int cash)
{
    int wonBalance = cash * CoinManager.WonPerPoint;
    int betWon = betAmount * CoinManager.WonPerPoint;
    creditText.text = $"보유 금액 {wonBalance:N0}원";
    betText.text = $"베팅 {betWon:N0}원";
    SetBetControlsInteractable(!isSpinning);
}

private IEnumerator ShowWinCelebration(int payout, float multiplier, int profit)
{
    int payoutWon = payout * CoinManager.WonPerPoint;
    int profitWon = profit * CoinManager.WonPerPoint;
    winOverlayText.text = $"{multiplier:0.#}배 당첨!\n{payoutWon:N0}원 지급\n순이익 +{profitWon:N0}원";
    winOverlay.SetActive(true);
    winOverlay.transform.SetAsLastSibling();
    winOverlayGroup.alpha = 1f;

    float elapsed = 0f;
    while (elapsed < 0.35f)
    {
        elapsed += Time.unscaledDeltaTime;
        float scale = Mathf.Lerp(0.55f, 1.15f, elapsed / 0.35f);
        winOverlayText.rectTransform.localScale = Vector3.one * scale;
        yield return null;
    }

    elapsed = 0f;
    while (elapsed < 0.18f)
    {
        elapsed += Time.unscaledDeltaTime;
        winOverlayText.rectTransform.localScale = Vector3.one * Mathf.Lerp(1.15f, 1f, elapsed / 0.18f);
        yield return null;
    }

    yield return new WaitForSecondsRealtime(0.85f);
    elapsed = 0f;
    while (elapsed < 0.35f)
    {
        elapsed += Time.unscaledDeltaTime;
        winOverlayGroup.alpha = 1f - elapsed / 0.35f;
        yield return null;
    }

    winOverlay.SetActive(false);
}

public void AttemptCashOut()
{
    if (gameEnded || coinManager == null)
        return;

    if (!CanAttemptCashOut)
    {
        ShowFeedback("환전할 금액이 없다.");
        return;
    }

    cashOutAttempts++;
    if (coinManager.CasinoCash >= CashOutEndingBalance || cashOutAttempts >= CashOutEndingAttempts)
    {
        TriggerScenario("cashout_scam");
        return;
    }

    if (!coinManager.TryCashOutCasino(out int points, out int won))
        return;

    TriggerScenario("cashout_success", new Dictionary<string, string>
    {
        ["points"] = points.ToString("N0"),
        ["won"] = won.ToString("N0")
    });
    ShowFeedback($"{won:N0}원이 통장으로 자동 환전됐다.");
    FindAnyObjectByType<CasinoUIManager>(FindObjectsInactive.Include)?.ReturnToHomeAfterCashOut();
    RefreshUI();
}

private string GetCashTransactionDescription(int amount)
{
    string sceneId = activeScene?.id ?? string.Empty;
    if (sceneId == "d1_intro")
        return "생활비";
    if (sceneId == "d6_mom_allowance")
        return "엄마 용돈";
    if (sceneId.StartsWith("gamble_", StringComparison.OrdinalIgnoreCase))
        return amount > 0 ? "도박 앱 자동 환전" : "도박 앱 결제";
    if (sceneId.Contains("mom_loan", StringComparison.OrdinalIgnoreCase))
        return "엄마에게 빌린 돈";
    if (sceneId.Contains("seojun_loan", StringComparison.OrdinalIgnoreCase))
        return "서준에게 빌린 돈";
    if (sceneId.Contains("minjae_loan", StringComparison.OrdinalIgnoreCase))
        return "민재에게 빌린 돈";
    return amount >= 0 ? "입금" : "결제";
}

